import{_ as t,o as r,c as a,a2 as i}from"./chunks/framework.DdtnLau3.js";const u=JSON.parse('{"title":"Work Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/work.md","filePath":"spec/work.md"}'),o={name:"spec/work.md"};function n(s,e,d,c,l,p){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="work-specification" tabindex="-1">Work Specification <a class="header-anchor" href="#work-specification" aria-label="Permalink to &quot;Work Specification&quot;">​</a></h1><h2 id="current-behavior" tabindex="-1">Current behavior <a class="header-anchor" href="#current-behavior" aria-label="Permalink to &quot;Current behavior&quot;">​</a></h2><p>A Work owns its configuration, private conversation history, shared workspace, Service definitions, and captured execution context. Core controls lifecycle and isolation.</p><p>Export requires a <strong>stopped Work</strong>. Import validates the archive and target requirements, then publishes a new <strong>stopped Work</strong>. It assigns new Work, Service, volume, network, certificate, and control identities. The recipient starts it explicitly.</p><p>Changing desired configuration does not immediately replace active context. Pending settings require an explicit Apply. Import preserves active and desired configuration without silently applying pending changes.</p><h2 id="current-format-work-v1" tabindex="-1">Current format: <code>.work</code> v1 <a class="header-anchor" href="#current-format-work-v1" aria-label="Permalink to &quot;Current format: `.work` v1&quot;">​</a></h2><p>The MIME type is <code>application/vnd.piwork.work-package</code>. The snapshot kind is <code>cold-full</code>.</p><table tabindex="0"><thead><tr><th>Bytes</th><th>Meaning</th></tr></thead><tbody><tr><td>Eight bytes <code>PIWORK1\\n</code></td><td>Format magic.</td></tr><tr><td>Unsigned 64-bit big-endian integer</td><td>UTF-8 JSON manifest length.</td></tr><tr><td>Manifest JSON</td><td>Strict format/version, compatibility, references, and blob metadata.</td></tr><tr><td>Ordered raw blobs</td><td>Each blob&#39;s declared byte length and SHA-256 digest.</td></tr></tbody></table><p>There are no blob headers, compression, or trailing bytes. Core creates the manifest; users do not hand-author it. The archive includes fixed image content by immutable digest.</p><p>Included durable content covers the <code>agent-private</code> and <code>workspace</code> volume trees, Work-owned contexts, <code>AGENTS.md</code>, Skills, prepared Pi Package artifacts, Service/configuration revisions, and retained history. Logical references are remapped on import; original user files and SDK history bytes are retained.</p><h2 id="portability-boundaries" tabindex="-1">Portability boundaries <a class="header-anchor" href="#portability-boundaries" aria-label="Permalink to &quot;Portability boundaries&quot;">​</a></h2><ul><li>Live processes, temporary container layers, anonymous volumes, tmpfs, and external services are excluded.</li><li>Platform model API keys, user tokens, installation certificates, and global catalogs are excluded.</li><li>User secrets in files and history are included because user content is not filtered.</li><li>Target Core must have an enabled matching model, readable credentials, compatible platform/images, and enough quota.</li><li>Offline inspection checks integrity and structure; it does not prove recipient compatibility or trust in embedded code.</li></ul><p>V1 is Linux and protocol/layout specific. Current limits include 100 GiB package bytes, 100 GiB logical restore size, and one million tree entries. Unsupported special files, user xattrs, ACLs, or capabilities fail export. The host-assigned <code>security.selinux</code> label is excluded, and restore uses the target host&#39;s label.</p><h2 id="experimental-and-future-direction" tabindex="-1">Experimental and future direction <a class="header-anchor" href="#experimental-and-future-direction" aria-label="Permalink to &quot;Experimental and future direction&quot;">​</a></h2><p>The current portable format is version 1; it is not a generic host backup or cross-platform process checkpoint. Broader portability is future direction, not part of this format&#39;s guarantees.</p><p>For the complete strict manifest, tree encoding, history validation, and limits, use the authoritative <a href="https://github.com/pphboy/piwork/blob/main/docs/work-package-format.md" target="_blank" rel="noreferrer">Work package format</a>, <a href="https://github.com/pphboy/piwork/blob/main/openspec/specs/portable-work/spec.md" target="_blank" rel="noreferrer">portable-work spec</a>, and <a href="https://github.com/pphboy/piwork/blob/main/docs/work-snapshot.md" target="_blank" rel="noreferrer">snapshot guide</a>.</p>',16)])])}const b=t(o,[["render",n]]);export{u as __pageData,b as default};
